"""Output guardrail: nothing generated by an LLM reaches the user unchecked.

Checks, in order
  1. secrets / system-prompt leakage            → BLOCK
  2. individual securities picks, guaranteed returns → BLOCK
  3. numeric grounding (every number must exist in the deterministic facts) → BLOCK
  4. PII, HTML/script, links, over-length       → CLEAN (redact / strip / truncate)

If an answer is blocked the caller falls back to the deterministic, evidence-backed
recommendations, so the user always gets a safe and correct reply.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Iterable

from guardrails.pii import redact_pii

MAX_OUTPUT_CHARS = 1800
_NUM_RE = re.compile(r"(?<![\w.])-?\d[\d,]*(?:\.\d+)?")
_SECURITIES_PICK = re.compile(
    r"\b(you should|i recommend|consider|go ahead and|better to)\b.{0,25}\b(buy|sell|short|invest in)\b.{0,40}"
    r"\b([A-Z]{3,6}\b|bitcoin|ethereum|dogecoin|crypto|nifty|sensex|stock|shares?|etf)\b",
    re.I,
)
_GUARANTEE = re.compile(r"\b(guaranteed|assured|risk[- ]?free|sure[- ]?shot)\b.{0,20}\b(returns?|profits?|gains?)\b", re.I)
_LEAK = re.compile(r"(system prompt|my instructions are|as an? (unrestricted|jailbroken)|developer mode|AIza[0-9A-Za-z_\-]{20,}|sk-[A-Za-z0-9]{20,})", re.I)
_HTML = re.compile(r"<[^>]{0,200}>")
_LINK = re.compile(r"(https?://\S+|www\.\S+|\[[^\]]*\]\([^)]*\))")


def extract_numbers(text: str) -> list[float]:
    out: list[float] = []
    for m in _NUM_RE.findall(str(text)):
        try:
            out.append(float(m.replace(",", "")))
        except ValueError:
            continue
    return out


def allowed_number_set(*sources: object) -> set[float]:
    """Collect every numeric value from deterministic facts, plus natural derivations."""
    allowed: set[float] = set()

    def add(v: float) -> None:
        allowed.add(round(v, 4))
        allowed.add(round(abs(v), 4))
        if abs(v) <= 5:
            allowed.add(round(v * 100, 4))        # fraction → percent
        if abs(v) >= 100_000:
            allowed.add(round(v / 100_000, 4))    # rupees → lakh
        if abs(v) >= 1000:
            allowed.add(round(v / 12, 2))         # annual → monthly style statements
        allowed.add(round(v * 12, 2)) if abs(v) < 1_000_000 else None

    def walk(obj: object) -> None:
        if isinstance(obj, bool) or obj is None:
            return
        if isinstance(obj, (int, float)):
            add(float(obj))
        elif isinstance(obj, str):
            for n in extract_numbers(obj):
                add(n)
        elif isinstance(obj, dict):
            for k, v in obj.items():
                walk(k)
                walk(v)
        elif isinstance(obj, (list, tuple, set)):
            for v in obj:
                walk(v)

    for s in sources:
        walk(s)
    return allowed


def _is_grounded(value: float, allowed: set[float]) -> bool:
    if 1900 <= value <= 2100 and float(value).is_integer():
        return True                                   # years
    if float(value).is_integer() and 0 <= value <= 60:
        return True                                   # small counts / months / days
    for a in allowed:
        if abs(value - a) <= max(1.0, abs(a) * 0.006):
            return True
    return False


def ungrounded_numbers(text: str, allowed: set[float]) -> list[float]:
    return sorted({n for n in extract_numbers(text) if not _is_grounded(n, allowed)})


@dataclass
class OutputCheck:
    ok: bool
    text: str
    violations: list[str] = field(default_factory=list)
    cleaned: list[str] = field(default_factory=list)


def check_output(text: str, facts: Iterable[object] | None = None) -> OutputCheck:
    raw = str(text or "").strip()
    if not raw:
        return OutputCheck(False, "", ["empty_output"])
    violations: list[str] = []

    if _LEAK.search(raw):
        violations.append("secret_or_prompt_leak")
    if _SECURITIES_PICK.search(raw):
        violations.append("individual_securities_recommendation")
    if _GUARANTEE.search(raw):
        violations.append("guaranteed_returns_claim")
    if facts is not None:
        bad = ungrounded_numbers(raw, allowed_number_set(*list(facts)))
        if bad:
            violations.append("ungrounded_numbers:" + ",".join(f"{b:g}" for b in bad[:6]))
    if violations:
        return OutputCheck(False, "", violations)

    cleaned: list[str] = []
    out = raw
    if _HTML.search(out):
        out = _HTML.sub("", out)
        cleaned.append("html_stripped")
    if _LINK.search(out):
        out = _LINK.sub("", out)
        cleaned.append("links_removed")
    out, redactions = redact_pii(out)
    if redactions:
        cleaned.append("pii_redacted:" + ",".join(redactions))
    if len(out) > MAX_OUTPUT_CHARS:
        out = out[:MAX_OUTPUT_CHARS].rsplit(" ", 1)[0] + "…"
        cleaned.append("truncated")
    return OutputCheck(True, out.strip(), [], cleaned)
